DDL = ["\nCREATE TABLE core_planner_invocations (\n\tid UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tevent_id UUID NOT NULL, \n\tattempt INTEGER NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\tcontext JSONB NOT NULL, \n\tresult JSONB, \n\treview JSONB, \n\tlease_token UUID, \n\tlease_until TIMESTAMP WITH TIME ZONE, \n\tnext_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, \n\tfailures INTEGER NOT NULL, \n\terror TEXT, \n\tcreated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, \n\tPRIMARY KEY (id), \n\tCHECK (attempt >= 0 AND failures >= 0), \n\tCHECK (status IN ('pending','calling','returned','done')), \n\tUNIQUE (event_id, attempt), \n\tFOREIGN KEY(run_id) REFERENCES core_runs (id), \n\tFOREIGN KEY(event_id) REFERENCES core_event_outbox (id)\n)\n\n", 'CREATE INDEX ix_core_planner_due ON core_planner_invocations (status, next_at, lease_until)']

def task_checks(waiting, queued):
    op.execute("""DO $$ DECLARE c record; BEGIN
      FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='core_tasks'::regclass AND contype='c'
        AND (pg_get_constraintdef(oid) LIKE '%waiting_user%kind%' OR
             pg_get_constraintdef(oid) LIKE '%kind%queued%submitted%') LOOP
        EXECUTE format('ALTER TABLE core_tasks DROP CONSTRAINT %I', c.conname);
      END LOOP;
    END $$""")
    op.create_check_constraint("ck_core_interaction_waiting", "core_tasks", waiting)
    op.create_check_constraint("ck_core_interaction_queue", "core_tasks", queued)


def upgrade():
    for statement in DDL:
        op.execute(statement)
    task_checks("status <> 'waiting_user' OR kind IN ('wait_user','ask_user')",
        "kind NOT IN ('wait_user','ask_user') OR status NOT IN ('queued','submitted')")
    op.execute(NEW_GUARD)
    op.execute("""CREATE FUNCTION core_guard_planner_result() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
      IF ROW(NEW.id,NEW.run_id,NEW.event_id,NEW.attempt) IS DISTINCT FROM ROW(OLD.id,OLD.run_id,OLD.event_id,OLD.attempt)
        OR (OLD.result IS NOT NULL AND (NEW.result IS DISTINCT FROM OLD.result OR NEW.context IS DISTINCT FROM OLD.context))
      THEN RAISE EXCEPTION 'planner output and invocation identity are immutable'; END IF;
      RETURN NEW; END $$""")
    op.execute("CREATE TRIGGER core_planner_result_guard BEFORE UPDATE ON core_planner_invocations FOR EACH ROW EXECUTE FUNCTION core_guard_planner_result()")


def downgrade():
    op.execute("""DO $$ BEGIN IF EXISTS(SELECT 1 FROM core_tasks WHERE kind='ask_user' AND status='waiting_user')
        THEN RAISE EXCEPTION 'resolve ask_user tasks before rollback'; END IF; END $$""")
    op.execute(OLD_GUARD)
    task_checks("status <> 'waiting_user' OR kind = 'wait_user'", "kind <> 'wait_user' OR status NOT IN ('queued','submitted')")
    op.drop_table("core_planner_invocations")
    op.execute("DROP FUNCTION core_guard_planner_result()")
